use vstd::prelude::*;

verus! {
    fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
        requires
            1 <= k < list.len(),
        ensures
            new_list.len() == list.len() - 1,
            forall |i: usize| (0 <= i < k - 1 ==> new_list[i] == list[i]) &&
            forall |i: usize| (k - 1 <= i < new_list.len() ==> new_list[i] == list[i + 1]),
    {
        let mut new_list: Vec<i32> = Vec::new();
        
        // Add elements before the k-th element
        let mut i: usize = 0;
        while i < list.len()
            invariant
                new_list.len() == i,
                i <= list.len(),
                new_list.len() <= list.len() - 1,
            decreases list.len() - i,
        {
            if i == k - 1 {
                // Skip the k-th element
                i = i + 1;
                continue;
            }
            new_list.push(list[i]);
            i = i + 1;
        }
        
        new_list
    }
}
